const cartStyle=document.createElement('style');cartStyle.textContent='.pack-cart-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,340px);gap:16px;align-items:start}.pack-cart-layout main{min-width:0;display:grid;gap:16px}.pack-cart-summary{position:sticky;top:12px;display:grid;gap:10px}.pack-cart-footer{position:sticky;bottom:0;padding:12px;background:var(--card,#fff);border-top:1px solid var(--line);z-index:3;justify-content:flex-end}.pack-cart-page input,.pack-cart-page select{width:100%;min-width:0}.pack-cart-page input[type=checkbox]{width:18px}.pack-cart-page .field{min-width:0;margin:4px 0;gap:6px}.pack-cart-page .field>span{font-size:13px;font-weight:600}.pack-cart-page input:not([type=checkbox]),.pack-cart-page select{min-height:38px;padding:8px 10px}.pack-cart-page #packPurchaseLines .grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pack-cart-page #packPurchaseLines .field:first-child,.pack-cart-page #packPurchaseLines .field:last-child{grid-column:1/-1}.pack-cart-page .pack-cart-table td:last-child{min-width:150px}.pack-cart-page .grid{gap:12px}@media(max-width:850px){.pack-cart-layout{grid-template-columns:minmax(0,1fr)}.pack-cart-summary{position:static}}';document.head.appendChild(cartStyle);
const style=document.createElement('style');style.textContent='.ps-pack-panel{margin:14px 0}.ps-packaging details,.pack-dialog details{margin:12px 0}.pack-dialog fieldset{border:1px solid var(--line);border-radius:10px;margin:12px 0;padding:12px}.pack-dialog .pack-footer{position:sticky;bottom:-16px;background:var(--card,#fff);padding:12px 0;z-index:2;border-top:1px solid var(--line)}.pack-error{color:#b42318}.pack-sidebar summary{cursor:pointer;padding:12px;color:inherit}.pack-sidebar button{padding-left:28px!important}.pack-sidebar summary::marker{font-size:12px}.ps-packaging .ps-detail-box b{display:block;overflow-wrap:anywhere}.ps-packaging .section-title{gap:12px;flex-wrap:wrap}.pack-dialog .field{min-width:0}.pack-dialog input:not([type=checkbox]),.pack-dialog select{width:100%}@media(max-width:700px){.ps-packaging .section-title form{width:100%}.ps-packaging .section-title form input{min-width:0;flex:1}.pack-dialog .ps-actions{flex-wrap:wrap}.pack-dialog .table input{max-width:90px}}';document.head.appendChild(style);
